{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Studies were included if: 1) they were published between January 1, 2000, and May 29, 2021; 2) they were written in English, German, or Dutch; 3) they used a quantitative, qualitative, or mixed-methods study design; and 4) the study population consisted of patients aged ≥ 65 years (baseline mean age of 65 years or older), caregivers, or HCPs... Studies were excluded if they were: 1) editorials, opinion papers, conference abstracts, or literature reviews; 2) targeting patients with moderate to severe dementia... or palliative patients; 3) studies with no original participant data regarding barriers and facilitators; and 4) studies that were performed in an inpatient rehabilitation or psychiatric unit, or in healthcare settings other than hospitals, such as outpatient clinics.",
      "reason": "The manuscript explicitly lists inclusion and exclusion criteria, covering study designs, publication dates, languages, population (age, type), and settings."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Studies were included if: 1) they were published between January 1, 2000, and May 29, 2021; 2) they were written in English, German, or Dutch",
      "reason": "The manuscript specifies the dissemination year range and language requirements for inclusion."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is a qualitative/mixed-methods synthesis of facilitators and barriers, not a meta-analysis of quantitative outcomes where 'outcomes not measured' vs 'results not reported' would be a standard distinction for exclusion."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Subsequently, the overall quality scores of each study were used to group studies into two categories: high (MMAT score 4 or 5) and low (MMAT score 0-3) quality.",
      "reason": "The manuscript specifies how studies were grouped for the synthesis (best evidence synthesis) based on quality scores (high vs. low) and study design."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Given the specific hospital setting in the current review, in which patients enter a different and unfamiliar context, it is conceivable that facilitators and barriers might be different for patients over 65 years than for younger patients.",
      "reason": "The manuscript provides a rationale for the restriction to patients aged 65+ and the specific hospital setting, noting that factors may differ for older patients in this specific context."
    }
  ],
  "confidence": 100
}

